265:
SELECT j."preferred_years"
FROM "jobs" j
WHERE j."salary" = (SELECT MAX("salary") FROM "jobs");

286:
SELECT DISTINCT d."degree_level"
FROM "degrees" d
WHERE LOWER(d."job_post") LIKE '%ai researcher%';

288:
SELECT DISTINCT d."certification"
FROM "degrees" d
WHERE LOWER(d."job_post") LIKE '%ai researcher%';

289:
SELECT DISTINCT d."degree_level", d."certification"
FROM "degrees" d
WHERE LOWER(d."job_post") LIKE '%ai researcher%';
